import{_ as e,o as d,c as o,a4 as a}from"./chunks/framework.DpieW3qv.js";const u=JSON.parse('{"title":"Command Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/commands.md","filePath":"reference/commands.md","lastUpdated":null}'),c={name:"reference/commands.md"};function r(i,t,s,l,h,n){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="command-reference" tabindex="-1">Command Reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command Reference&quot;">​</a></h1><p>Quick reference for all Makefile commands. For full syntax, flags, and example output, use the per-command pages under <a href="/ocapi-docs.github.io/cli/">Commands</a>.</p><h2 id="command-summary" tabindex="-1">Command summary <a class="header-anchor" href="#command-summary" aria-label="Permalink to &quot;Command summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Command</th><th>What it does</th><th>Typical output</th></tr></thead><tbody><tr><td>Setup</td><td><code>make setup</code></td><td>Configure brand, data source, OCAPI</td><td>Wizard; writes <code>dev-env/.ocapi-config.json</code></td></tr><tr><td>Setup</td><td><code>make switch TO=ann</code></td><td>Switch brand</td><td>Updates config for Ann Taylor</td></tr><tr><td>Setup</td><td><code>make health</code></td><td>Test SFCC connection</td><td><code>✔ OCAPI ready (NNNms)</code> or missing-env errors</td></tr><tr><td>1</td><td><code>make pull</code></td><td>Git sync + fetch + pick date</td><td>Fetch results; date picker; &quot;Next: make build&quot;</td></tr><tr><td>2</td><td><code>make select</code></td><td>Set active refresh (sticky)</td><td><code>✔ Selected YYYY-MM-DD / r1</code> or picker</td></tr><tr><td>3</td><td><code>make build</code></td><td>Generate HTML + OCAPI payload</td><td><code>✔ N files generated</code> or &quot;Already built&quot; / &quot;Already synced&quot;</td></tr><tr><td>4</td><td><code>make build FORCE=1</code></td><td>Force rebuild (bypass guard)</td><td>Same as build</td></tr><tr><td>5</td><td><code>make preview</code></td><td>Show preview links</td><td>Links per asset type; Section Picker</td></tr><tr><td>6</td><td><code>make push</code></td><td>Validate + sync to SFCC</td><td><code>✔ Synced …: X created, Y updated</code> or &quot;no changes to sync&quot;</td></tr><tr><td>7</td><td><code>make replicate</code></td><td>Staging → production checklist</td><td>Checklist; &quot;Next: make email&quot;</td></tr><tr><td>8</td><td><code>make email</code></td><td>Generate changeout email</td><td>Email body (<code>make done</code> is alias)</td></tr><tr><td>9</td><td><code>make commit</code></td><td>Save to Git (refresh dir only)</td><td><code>✔ Committed: brand date done</code></td></tr><tr><td>Status</td><td><code>make status</code></td><td>Dashboard + action picker; selection sets active</td><td>Summary + picker (TTY) or full table</td></tr><tr><td>Dev</td><td><code>make delete DATE=</code></td><td>Remove refresh from SFCC + local</td><td><code>✔ SFCC deleted</code> / <code>✔ Deleted local</code></td></tr><tr><td>Dev</td><td><code>make upload</code></td><td>Partial asset sync (hotfix)</td><td>Sync summary</td></tr><tr><td>Dev</td><td><code>make registry</code></td><td>Show live asset registry</td><td>Zone list + item counts</td></tr><tr><td>Dev</td><td><code>make registry-ipids</code></td><td>List all IPIDs in the registry</td><td>Asset type, zone, order, IPID</td></tr><tr><td>Dev</td><td><code>make test</code></td><td>Run unit tests (Vitest)</td><td><code>Tests N passed</code></td></tr><tr><td>Dev</td><td><code>make check</code></td><td>Lint + tests + audit (CI gate)</td><td>Lint + test + audit output</td></tr><tr><td>Dev</td><td><code>make clean</code></td><td>Remove rendered previews</td><td><code>✔ Cleaned</code></td></tr><tr><td>Dev</td><td><code>make docs</code></td><td>Start docs dev server</td><td>VitePress URL</td></tr><tr><td>Dev</td><td><code>make reports [OP=dates]</code></td><td>Report: dates, stats, status, pending, history</td><td>See <a href="/ocapi-docs.github.io/cli/reports.html">reports</a></td></tr><tr><td>Dev</td><td><code>make validate [DATE=]</code></td><td>Data quality check only (no build/push)</td><td>See <a href="/ocapi-docs.github.io/cli/validate.html">validate</a></td></tr><tr><td>CI</td><td><code>make test-sync DATE=</code></td><td>Push to OCAPI with <code>--yes --force</code> (CI / non-interactive)</td><td>Sync output</td></tr><tr><td>CI</td><td><code>make build-all [FORCE=1]</code></td><td>Build <strong>every</strong> date for current brand (no watcher)</td><td>Per-date build output</td></tr><tr><td>CI</td><td><code>make push-all [YES=1] [FORCE=1]</code></td><td>Sync <strong>every</strong> date to SFCC (run after build-all)</td><td>Per-date sync output</td></tr></tbody></table><p><strong>build-all / push-all:</strong> For CI or batch runs. Run <code>make pull</code> first; then <code>make build-all</code> builds all dates without starting the file watcher; then <code>make push-all</code> syncs all of them to SFCC. Use <code>YES=1</code> to skip confirmation prompts.</p><p><strong>Push behavior:</strong> Once a refresh is synced, <code>make push</code> for that refresh exits with &quot;SFCC already has this date; no changes to sync&quot;. Use <code>make push FORCE=1</code> to re-push (e.g. after hotfix). Next step after push: <code>make replicate</code>.</p><p><strong>Automation:</strong> For scripts and CI, use <code>DATE=</code>, <code>REFRESH=</code>, <code>YES=1</code>, <code>FORCE=1</code> as needed. Use <code>VERBOSE=1</code> for run IDs on log lines.</p><h2 id="make-variables-→-cli-flags" tabindex="-1">Make variables → CLI flags <a class="header-anchor" href="#make-variables-→-cli-flags" aria-label="Permalink to &quot;Make variables → CLI flags&quot;">​</a></h2><p>The Makefile is the source of truth. All commands are invoked via <code>make &lt;target&gt;</code>; the CLI receives variables as flags.</p><table tabindex="0"><thead><tr><th>Make variable</th><th>CLI flag / behaviour</th><th>Example</th></tr></thead><tbody><tr><td><code>BRAND</code></td><td>First positional arg after command</td><td><code>make build</code> → <code>node … refresh loft</code></td></tr><tr><td><code>DATE</code></td><td><code>--date=YYYY-MM-DD</code></td><td><code>make build DATE=2026-02-14</code></td></tr><tr><td><code>REFRESH</code></td><td><code>--refresh=r1</code></td><td><code>make push REFRESH=r2</code></td></tr><tr><td><code>FORCE=1</code></td><td><code>--force</code></td><td><code>make build FORCE=1</code></td></tr><tr><td><code>YES=1</code></td><td><code>--yes</code></td><td><code>make push-all YES=1</code></td></tr><tr><td><code>ALL=1</code> or <code>ALL</code></td><td><code>--all-refreshes</code> or <code>--show-all</code></td><td><code>make status ALL=1</code></td></tr><tr><td><code>SKIP_FETCH=1</code></td><td><code>--skip-fetch</code></td><td><code>make pull SKIP_FETCH=1</code></td></tr><tr><td><code>CONVERT=1</code></td><td><code>--convert</code></td><td><code>make pull CONVERT=1</code></td></tr><tr><td><code>VERBOSE=1</code></td><td><code>--verbose</code></td><td><code>make push VERBOSE=1</code></td></tr><tr><td><code>COPY=1</code></td><td><code>--copy</code></td><td><code>make email COPY=1</code></td></tr><tr><td><code>TO</code></td><td>(switch target)</td><td><code>make switch TO=ann</code></td></tr><tr><td><code>OP</code></td><td>(reports operation)</td><td><code>make reports OP=stats</code> (default: dates)</td></tr></tbody></table><h2 id="per-command-pages" tabindex="-1">Per-command pages <a class="header-anchor" href="#per-command-pages" aria-label="Permalink to &quot;Per-command pages&quot;">​</a></h2><ul><li><strong>Producer:</strong> <a href="/ocapi-docs.github.io/cli/status.html">status</a> · <a href="/ocapi-docs.github.io/cli/pull.html">pull</a> · <a href="/ocapi-docs.github.io/cli/select.html">select</a> · <a href="/ocapi-docs.github.io/cli/build.html">build</a> · <a href="/ocapi-docs.github.io/cli/preview.html">preview</a> · <a href="/ocapi-docs.github.io/cli/push.html">push</a> · <a href="/ocapi-docs.github.io/cli/replicate.html">replicate</a> · <a href="/ocapi-docs.github.io/cli/done.html">done</a> · <a href="/ocapi-docs.github.io/cli/email.html">email</a> · <a href="/ocapi-docs.github.io/cli/commit.html">commit</a> · <a href="/ocapi-docs.github.io/cli/refresh.html">refresh</a></li><li><strong>Dev &amp; Ops:</strong> <a href="/ocapi-docs.github.io/cli/setup.html">setup</a> · <a href="/ocapi-docs.github.io/cli/upload.html">upload</a> · <a href="/ocapi-docs.github.io/cli/delete.html">delete</a> · <a href="/ocapi-docs.github.io/cli/registry.html">registry</a> · <a href="/ocapi-docs.github.io/cli/health.html">health</a> · <a href="/ocapi-docs.github.io/cli/excel.html">excel</a> · <a href="/ocapi-docs.github.io/cli/reports.html">reports</a> · <a href="/ocapi-docs.github.io/cli/validate.html">validate</a> · <a href="/ocapi-docs.github.io/cli/sync.html">sync</a></li></ul><p>For full workflow and example output, see <a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Workflow</a>.</p>',13)])])}const p=e(c,[["render",r]]);export{u as __pageData,p as default};
